from typing import List

def separate_paren_groups(paren_string: str) -> List[str]:
    paren_string = paren_string.replace(" ", "")  # Step 1: Remove spaces from the input string
    result = []
    stack = []
    start = 0

    for i, char in enumerate(paren_string):
        if char == '(':
            stack.append(i)
        elif char == ')':
            if stack:
                start = stack.pop()
                result.append(paren_string[start:i+1])  # Step 2: Identify and separate the groups of nested parentheses

    return [group for group in result if group.count('(') == group.count(')')]  # Step 3: Check each substring to ensure it is a minimal valid parenthesis group

